with filtered as (select *, concat_ws('-', method, status) as method_status_key, coalesce(method, 'UNKNOWN') as method_clean from payments where order_id is not null) select *, avg(amount) over (partition by status, order_id order by amount, id rows between 5 preceding and 1 preceding) as amount_avg_5_prior, count(amount) over (partition by status order by cast(paid_at as bigint) range between 2592000 preceding and current row) as amount_count_30d, row_number() over (partition by order_id order by amount desc, id) as seq_no, sum(amount) over (partition by method order by amount, id rows between unbounded preceding and current row) as running_amount, percent_rank() over (partition by method order by amount desc) as amount_percent_rank from filtered
